    - apply kalign_intro; [lia|]. cbn [edenot]. rewrite snp_ev1. assumption.
    - apply krange_intro. cbn [edenot]. rewrite snp_ev1. lia.
    - apply (kwr_of_stk_ok RSEGS E mem (EVar 0) sp 6144); [apply snp_ev0 | exact Nstk0 | unfold SNP_FR; lia].
    - cbn [kentry_ok]. unfold flat, estart. cbn [a_base a_off edenot]. rewrite snp_ev1.
      split; [lia|]. intros d m Hd Hm. apply Nbuf0; lia.
    - cbn [kentry_ok]. unfold estart. cbn [a_base a_off edenot]. rewrite snp_ev0, snp_ev1. lia.
    - apply kimg_intro; [lia | lia | exact Nimg0].
    - eapply (kword_intro RSEGS E mem (ELit 0) (Z_to_bv 64 0)); [reflexivity | apply snp_ev2 | lia | lia | rewrite Z0; lia | rewrite Z0; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia | rewrite Z0; exact Ncan0].
  Qed.
