      /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 6144), 6144); (Z_to_bv 64 (bv_unsigned Fb + 32), 3)]
      /\ rdn RSEGS mem' (Z_to_bv 64 (bv_unsigned Fb + 32)) 1 = Some [Z_to_bv 8 45]
      /\ rdn RSEGS mem' (Z_to_bv 64 (bv_unsigned Fb + 33)) 1 = Some [Z_to_bv 8 49]
      /\ rdn RSEGS mem' (Z_to_bv 64 (bv_unsigned Fb + 34)) 1 = Some [Z_to_bv 8 0]
      /\ rsh regs'.

  Lemma snp_pack : forall reads scr ss' scs scr' kn' hs',
    sym_exec RSEGS 8000 true [SNP_RET] (SCR scr [] []) (SS SNP_ENTRY snp_sr [] (snp_kn reads) 35) [] = (ss', scs, scr') ->
    know_ok RSEGS E mem reads -> scs_denot RSEGS mem E scs ->
    s_pc ss' = SNP_RET ->
    log_covered snp_regions3 (s_log ss') = true ->
    same_regs snp_sr (s_regs ss') callee_saved = true ->
    nth 10 (s_regs ss') (ELit 0) = A0EXPR ->
    carry (s_log ss') (snp_kn reads) [] = (kn', [], hs') ->
    kread RSEGS kn' (EVar 1) 32 1 = Some (ELit 45) ->
    kread RSEGS kn' (EVar 1) 33 1 = Some (ELit 49) ->
    kread RSEGS kn' (EVar 1) 34 1 = Some (ELit 0) ->
    exists regs' mem', snp_post regs' mem'.
  Proof.
    intros reads scr ss' scs scr' kn' hs' Hrun HKR HSC Hpc Hcov Hsame H10 Hcarry K0 K1 K2.
    pose proof (snp_regs_ok regs mem sp Fb can SH R2 R10 R11 R12 R13) as HR.
    assert (HK : know_ok RSEGS E mem (snp_kn reads)).
    { unfold snp_kn. apply Forall_app. split; [exact (snp_know0_ok regs mem sp Fb can SH) | exact HKR]. }
    fold E in HR.
    destruct (run_sound RSEGS rsh rsh_upd 8000 [SNP_RET] (SCR scr [] []) SNP_ENTRY snp_sr (snp_kn reads) 35 ss' scs scr' E mem rom regs
                Hrun HR HK HSC RSH) as (R' & HR' & Hlf & Hms & HSH').
    rewrite Hpc in Hms.
    assert (HK' : know_ok RSEGS E (mem_denot E mem (s_log ss')) kn').
    { eapply carry_after; [exact Hcarry | exact Hlf | exact HK | constructor]. }
    destruct SH. pose proof (u64_range sp) as Hsp. pose proof (u64_range Fb) as Hf.
    exists R', (mem_denot E mem (s_log ss')). unfold snp_post.
    split; [exact Hms|]. split; [|split; [|split; [|split; [|split; [|split; [|exact HSH']]]]]].
    - eapply (keeps_cs_of_same E); [exact Hsame | exact HR | exact HR'].
    - rewrite (reg_val E _ _ 10 HR').
      replace (sr_get (s_regs ss') 10) with (nth 10 (s_regs ss') (ELit 0)) by reflexivity.
      rewrite H10. exact (a0_val regs mem sp Fb can (SNPH _ _ _ _ Nsp17 NspLo0 NspHi0 NfLo0 NfHi0 Nf65 Ndj0 Ninm0 Nstk0 Nbuf0 Nimg0 Ncan0 Ncan65 Ncells0 Nsh1 Nhead0 Nhead5 Nro0)).
    - replace [(Z_to_bv 64 (bv_unsigned sp - 6144), 6144); (Z_to_bv 64 (bv_unsigned Fb + 32), 3)]
        with (map (rdenot E) snp_regions3).
      2:{ unfold snp_regions3, rdenot, estart. cbn [map fst snd a_base a_off edenot].
          change (ev E 0) with sp. change (ev E 1) with Fb. reflexivity. }
      apply log_covered_frame; [exact Hcov | | exact Hlf].
      intros r Hr. unfold snp_regions3 in Hr. cbn [In] in Hr.
      unfold flat, estart.
      destruct Hr as [<-|[<-|[]]]; cbn [fst snd a_base a_off edenot]; [change (ev E 0) with sp | change (ev E 1) with Fb]; lia.
    - pose proof (kread_rdn RSEGS E _ kn' (EVar 1) 32 1 _ HK' K0 ltac:(lia) ltac:(lia)) as B.
      unfold adenot in B. cbn [a_base a_off edenot] in B. change (ev E 1) with Fb in B. unfold v_addi in B.
      apply B. unfold flat, estart. cbn [a_base a_off edenot]. change (ev E 1) with Fb. lia.
    - pose proof (kread_rdn RSEGS E _ kn' (EVar 1) 33 1 _ HK' K1 ltac:(lia) ltac:(lia)) as B.
      unfold adenot in B. cbn [a_base a_off edenot] in B. change (ev E 1) with Fb in B. unfold v_addi in B.
      apply B. unfold flat, estart. cbn [a_base a_off edenot]. change (ev E 1) with Fb. lia.
    - pose proof (kread_rdn RSEGS E _ kn' (EVar 1) 34 1 _ HK' K2 ltac:(lia) ltac:(lia)) as B.
      unfold adenot in B. cbn [a_base a_off edenot] in B. change (ev E 1) with Fb in B. unfold v_addi in B.
      apply B. unfold flat, estart. cbn [a_base a_off edenot]. change (ev E 1) with Fb. lia.
  Qed.
End Package.
